#include <assert.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_SIZE 48
struct Product { int id; char name[NAME_SIZE]; int quantity; long long price_cents; };
struct Inventory { struct Product *items; size_t count; size_t capacity; };

static int valid_product(const struct Product *p) {
    return p != NULL && p->id > 0 && p->name[0] != '\0'
        && strlen(p->name) < NAME_SIZE && p->quantity >= 0 && p->price_cents > 0;
}
static size_t find_product(const struct Inventory *inv, int id) {
    size_t i;
    for (i=0; i<inv->count; ++i) if (inv->items[i].id==id) return i;
    return inv->count;
}
static int reserve_products(struct Inventory *inv, size_t needed) {
    size_t cap;
    struct Product *tmp;
    if (needed<=inv->capacity) return 1;
    if (needed>SIZE_MAX/sizeof *inv->items) return 0;
    cap=inv->capacity==0U?2U:inv->capacity;
    while(cap<needed) { if(cap>SIZE_MAX/2U){cap=needed;break;} cap*=2U; }
    if(cap>SIZE_MAX/sizeof *inv->items) return 0;
    tmp=realloc(inv->items,cap*sizeof *inv->items);
    if(tmp==NULL) return 0;
    inv->items=tmp; inv->capacity=cap; return 1;
}
static int add_product(struct Inventory *inv,const struct Product *p) {
    if(!valid_product(p)||find_product(inv,p->id)!=inv->count||inv->count==SIZE_MAX) return 0;
    if(!reserve_products(inv,inv->count+1U)) return 0;
    inv->items[inv->count++]=*p; return 1;
}
static int change_stock(struct Inventory *inv,int id,int delta) {
    size_t at=find_product(inv,id);
    if(at==inv->count) return 0;
    if(delta<0 && inv->items[at].quantity < -delta) return 0;
    if(delta>0 && inv->items[at].quantity > INT_MAX-delta) return 0;
    if(inv->items[at].quantity+delta<0) return 0;
    inv->items[at].quantity+=delta; return 1;
}
static int update_price(struct Inventory *inv,int id,long long cents) {
    size_t at=find_product(inv,id);
    if(at==inv->count||cents<=0) return 0;
    inv->items[at].price_cents=cents; return 1;
}
static int delete_product(struct Inventory *inv,int id) {
    size_t at=find_product(inv,id),i;
    if(at==inv->count) return 0;
    for(i=at;i+1U<inv->count;++i) inv->items[i]=inv->items[i+1U];
    --inv->count; return 1;
}
static void destroy_inventory(struct Inventory *inv) {
    free(inv->items); inv->items=NULL; inv->count=0U; inv->capacity=0U;
}
int main(void) {
    struct Inventory inv={NULL,0U,0U};
    const struct Product a={101,"USB Cable",10,1250};
    const struct Product b={102,"Wireless Mouse",5,7999};
    const struct Product duplicate={101,"Duplicate",1,100};
    const struct Product invalid={103,"Bad Price",1,0};
    assert(add_product(&inv,&a)); assert(add_product(&inv,&b));
    assert(!add_product(&inv,&duplicate)); assert(!add_product(&inv,&invalid));
    assert(find_product(&inv,102)==1U); assert(find_product(&inv,999)==inv.count);
    assert(change_stock(&inv,101,5)); assert(inv.items[0].quantity==15);
    assert(!change_stock(&inv,101,-16)); assert(!change_stock(&inv,999,1));
    assert(update_price(&inv,102,8500)); assert(!update_price(&inv,102,0));
    assert(delete_product(&inv,101)); assert(inv.count==1U&&inv.items[0].id==102);
    assert(!delete_product(&inv,101));
    destroy_inventory(&inv); assert(inv.items==NULL&&inv.count==0U&&inv.capacity==0U);
    puts("Inventory operation tests passed."); return 0;
}

#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_SIZE 48
#define LINE_SIZE 128
#define FILE_LINE_SIZE 128
#define DATA_FILE "inventory.txt"
#define TEMP_FILE "inventory.tmp"

struct Product { int id; char name[NAME_SIZE]; int quantity; long long price_cents; };
struct Inventory { struct Product *items; size_t count; size_t capacity; };
enum ReadResult { READ_OK, READ_END, READ_BAD };

static char *trim(char *s) {
    char *start=s,*end;
    while(isspace((unsigned char)*start)) ++start;
    end=start+strlen(start);
    while(end>start&&isspace((unsigned char)end[-1])) --end;
    *end='\0'; return start;
}
static enum ReadResult read_line(const char *prompt,char *buf,size_t size) {
    size_t n; int ch; fputs(prompt,stdout);
    if(fgets(buf,(int)size,stdin)==NULL) return READ_END;
    n=strlen(buf);
    if(n>0U&&buf[n-1U]=='\n'){buf[n-1U]='\0';return READ_OK;}
    ch=getchar(); if(ch=='\n'||ch==EOF) return READ_OK;
    while(ch!='\n'&&ch!=EOF) ch=getchar();
    return READ_BAD;
}
static int read_long(const char *prompt,long min,long max,long *out) {
    char line[LINE_SIZE],*s,*end; long v; enum ReadResult r=read_line(prompt,line,sizeof line);
    if(r!=READ_OK) return r==READ_END?0:-1;
    s=trim(line); errno=0; v=strtol(s,&end,10);
    while(isspace((unsigned char)*end)) ++end;
    if(s==end||*end!='\0'||errno==ERANGE||v<min||v>max) return -1;
    *out=v; return 1;
}
static int read_money(const char *prompt,long long *out) {
    char line[LINE_SIZE],*s,*p; unsigned long long whole=0ULL; unsigned int frac=0U;
    int digits=0,decimals=0; enum ReadResult r=read_line(prompt,line,sizeof line);
    if(r!=READ_OK) return r==READ_END?0:-1;
    s=trim(line); p=s;
    while(*p>='0'&&*p<='9'){
        unsigned int d=(unsigned int)(*p-'0');
        if(whole>((unsigned long long)LLONG_MAX/100ULL-d)/10ULL) return -1;
        whole=whole*10ULL+d; ++digits; ++p;
    }
    if(*p=='.'){++p;while(*p>='0'&&*p<='9'&&decimals<2){frac=frac*10U+(unsigned int)(*p-'0');++decimals;++p;} if(decimals==0)return -1;}
    if(*p!='\0'||digits==0)return -1;
    if(decimals==1)frac*=10U;
    if(whole>(unsigned long long)LLONG_MAX/100ULL||whole*100ULL>(unsigned long long)LLONG_MAX-frac)return -1;
    *out=(long long)(whole*100ULL+frac); return *out>0?1:-1;
}
static int read_name(char name[NAME_SIZE]) {
    char line[LINE_SIZE],*s; size_t n; enum ReadResult r=read_line("Product name (no |): ",line,sizeof line);
    if(r!=READ_OK)return r==READ_END?0:-1;
    s=trim(line);n=strlen(s);
    if(n==0U||n>=NAME_SIZE||strchr(s,'|')!=NULL)return -1;
    memcpy(name,s,n+1U);return 1;
}
static size_t find_product(const struct Inventory *inv,int id) {
    size_t i;for(i=0;i<inv->count;++i)if(inv->items[i].id==id)return i;return inv->count;
}
static int reserve_products(struct Inventory *inv,size_t needed) {
    size_t cap;struct Product *tmp;
    if(needed<=inv->capacity)return 1;
    if(needed>SIZE_MAX/sizeof *inv->items)return 0;
    cap=inv->capacity==0U?4U:inv->capacity;
    while(cap<needed){if(cap>SIZE_MAX/2U){cap=needed;break;}cap*=2U;}
    if(cap>SIZE_MAX/sizeof *inv->items)return 0;
    tmp=realloc(inv->items,cap*sizeof *inv->items);if(tmp==NULL)return 0;
    inv->items=tmp;inv->capacity=cap;return 1;
}
static int add_product(struct Inventory *inv,const struct Product *p) {
    if(p->id<=0||p->name[0]=='\0'||strlen(p->name)>=NAME_SIZE||p->quantity<0||p->price_cents<=0||find_product(inv,p->id)!=inv->count||inv->count==SIZE_MAX)return 0;
    if(!reserve_products(inv,inv->count+1U))return 0;
    inv->items[inv->count++]=*p;return 1;
}
static int save_inventory(const struct Inventory *inv) {
    FILE *f=fopen(TEMP_FILE,"w");size_t i;int ok=1;
    if(f==NULL){perror("Open temporary inventory file");return 0;}
    for(i=0;i<inv->count;++i){
        const struct Product *p=&inv->items[i];
        if(fprintf(f,"%d|%s|%d|%lld\n",p->id,p->name,p->quantity,p->price_cents)<0){ok=0;break;}
    }
    if(fclose(f)==EOF)ok=0;
    if(!ok){remove(TEMP_FILE);puts("Could not write inventory snapshot.");return 0;}
    if(rename(TEMP_FILE,DATA_FILE)!=0){perror("Could not replace inventory file");remove(TEMP_FILE);return 0;}
    return 1;
}
static int parse_record(char *line,struct Product *p) {
    char *a,*b,*c,*end;long id,qty;long long cents;
    size_t n=strlen(line);while(n>0U&&(line[n-1U]=='\n'||line[n-1U]=='\r'))line[--n]='\0';
    a=strchr(line,'|');if(a==NULL)return 0;*a++='\0';
    b=strchr(a,'|');if(b==NULL)return 0;*b++='\0';
    c=strchr(b,'|');if(c==NULL||strchr(c+1,'|')!=NULL)return 0;*c++='\0';
    errno=0;id=strtol(line,&end,10);if(errno==ERANGE||end==line||*end!='\0'||id<1||id>INT_MAX)return 0;
    if(a[0]=='\0'||strlen(a)>=NAME_SIZE)return 0;
    errno=0;qty=strtol(b,&end,10);if(errno==ERANGE||end==b||*end!='\0'||qty<0||qty>INT_MAX)return 0;
    errno=0;cents=strtoll(c,&end,10);if(errno==ERANGE||end==c||*end!='\0'||cents<=0)return 0;
    p->id=(int)id;p->quantity=(int)qty;p->price_cents=cents;
    (void)snprintf(p->name,sizeof p->name,"%s",a);return 1;
}
static void load_inventory(struct Inventory *inv) {
    FILE *f=fopen(DATA_FILE,"r");char line[FILE_LINE_SIZE];size_t bad=0U;
    if(f==NULL){if(errno==ENOENT){puts("No saved inventory yet; starting empty.");return;}perror("Open inventory file");return;}
    while(fgets(line,sizeof line,f)!=NULL){
        size_t n=strlen(line);struct Product p;
        if(n>0U&&line[n-1U]!='\n'&&!feof(f)){int ch;while((ch=fgetc(f))!='\n'&&ch!=EOF){};++bad;continue;}
        if(!parse_record(line,&p)||!add_product(inv,&p)){++bad;}
    }
    if(ferror(f))perror("Read inventory file");
    if(fclose(f)==EOF)perror("Close inventory file");
    printf("Loaded %zu products; skipped %zu invalid or duplicate records.\n",inv->count,bad);
}
static void list_products(const struct Inventory *inv) {
    size_t i;if(inv->count==0U){puts("Inventory is empty.");return;}
    puts("\nID     PRODUCT                                  QTY      PRICE");
    for(i=0;i<inv->count;++i){const struct Product *p=&inv->items[i];
        printf("%-6d %-40s %-8d %lld.%02lld%s\n",p->id,p->name,p->quantity,p->price_cents/100LL,p->price_cents%100LL,p->quantity<=5?"  LOW STOCK":"");
    }
}
static void add_menu(struct Inventory *inv) {
    struct Product p;long v;int r;
    r=(int)read_long("Product ID: ",1L,(long)INT_MAX,&v);if(r!=1){puts(r==0?"Input ended.":"Invalid ID.");return;}p.id=(int)v;
    if(find_product(inv,p.id)!=inv->count){puts("Product ID already exists.");return;}
    r=read_name(p.name);if(r!=1){puts(r==0?"Input ended.":"Invalid product name.");return;}
    r=(int)read_long("Opening quantity: ",0L,(long)INT_MAX,&v);if(r!=1){puts(r==0?"Input ended.":"Invalid quantity.");return;}p.quantity=(int)v;
    r=read_money("Unit price (e.g. 19.95): ",&p.price_cents);if(r!=1){puts(r==0?"Input ended.":"Invalid price.");return;}
    if(!add_product(inv,&p)){puts("Could not add product (memory or validation failure).");return;}
    puts("Product added. Save to persist changes.");
}
static void stock_menu(struct Inventory *inv,int add) {
    long id,amount;int r;size_t at;
    r=(int)read_long("Product ID: ",1L,(long)INT_MAX,&id);if(r!=1){puts(r==0?"Input ended.":"Invalid ID.");return;}
    at=find_product(inv,(int)id);if(at==inv->count){puts("Product not found.");return;}
    r=(int)read_long(add?"Quantity to add: ":"Quantity to remove: ",1L,(long)INT_MAX,&amount);if(r!=1){puts(r==0?"Input ended.":"Invalid quantity.");return;}
    if(add){if(inv->items[at].quantity>INT_MAX-(int)amount){puts("Quantity would overflow.");return;}inv->items[at].quantity+=(int)amount;}
    else{if(inv->items[at].quantity<(int)amount){puts("Insufficient stock.");return;}inv->items[at].quantity-=(int)amount;}
    puts("Stock updated. Save to persist changes.");
}
static void search_menu(const struct Inventory *inv) {
    long id;int r=(int)read_long("Product ID: ",1L,(long)INT_MAX,&id);size_t at;
    if(r!=1){puts(r==0?"Input ended.":"Invalid ID.");return;}
    at=find_product(inv,(int)id);if(at==inv->count)puts("Product not found.");
    else printf("%d | %s | quantity %d | %lld.%02lld\n",inv->items[at].id,inv->items[at].name,inv->items[at].quantity,inv->items[at].price_cents/100LL,inv->items[at].price_cents%100LL);
}
int main(void) {
    struct Inventory inv={NULL,0U,0U};int done=0;load_inventory(&inv);
    while(!done){
        char line[LINE_SIZE],*s,*end;long choice;enum ReadResult rr;
        puts("\nINVENTORY MANAGER");
        puts("1 Add  2 List/low stock  3 Search  4 Stock in  5 Stock out  6 Save  0 Exit");
        rr=read_line("Choose: ",line,sizeof line);
        if(rr==READ_END){puts("\nEnd of input.");break;}
        if(rr!=READ_OK){puts("Menu input too long.");continue;}
        s=trim(line);errno=0;choice=strtol(s,&end,10);while(isspace((unsigned char)*end))++end;
        if(s==end||*end!='\0'||errno==ERANGE||choice<0||choice>6){puts("Choose 0 to 6.");continue;}
        switch(choice){
            case 1:add_menu(&inv);break;
            case 2:list_products(&inv);break;
            case 3:search_menu(&inv);break;
            case 4:stock_menu(&inv,1);break;
            case 5:stock_menu(&inv,0);break;
            case 6:if(save_inventory(&inv))puts("Inventory saved.");break;
            case 0:done=1;break;
            default:break;
        }
    }
    free(inv.items);inv.items=NULL;inv.count=0U;inv.capacity=0U;
    puts("Inventory memory released. Goodbye.");return 0;
}
